messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>3D Humanoid Cycle</title>
    <style>
        body { margin:0; overflow:hidden; }
        canvas { position:absolute; top:0; left:0; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        const groundGeometry = new THREE.PlaneGeometry(10, 2);
        const groundMaterial = new THREE.MeshBasicMaterial({ color: 0x888888 });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI/2;
        scene.add(ground);

        const humanoid = new THREE.Group();
        scene.add(humanoid);

        const bodyGeometry = new THREE.SphereGeometry(1, 8, 8);
        const bodyMaterial = new THREE.MeshBasicMaterial({ color: 0xff0000 });
        const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
        body.position.y = 1; // torso sits on ground
        humanoid.add(body);

        const legGeometry = new THREE.CylinderGeometry(0.5, 0.5, 2, 8, 8);
        const legMaterial = new THREE.MeshBasicMaterial({ color: 0x0000ff });
        const leg1 = new THREE.Mesh(legGeometry, legMaterial);
        const leg2 = new THREE.Mesh(legGeometry, legMaterial);
        leg1.position.y = 0; leg1.rotation.z = Math.PI/2; // right leg
        leg2.position.y = 0; leg2.rotation.z = -Math.PI/2; // left leg
        humanoid.add(leg1);
        humanoid.add(leg2);

        const armGeometry = new THREE.CylinderGeometry(0.5, 0.5, 2, 8, 8);
        const armMaterial = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
        const arm1 = new THREE.Mesh(armGeometry, armMaterial);
        const arm2 = new THREE.Mesh(armGeometry, armMaterial);
        arm1.position.y = 1; arm1.rotation.z = Math.PI/2; // right arm
        arm2.position.y = 1; arm2.rotation.z = -Math.PI/2; // left arm
        humanoid.add(arm1);
        humanoid.add(arm2);

        const limbRotation = { leg1: Math.PI/2, leg2: -Math.PI/2, arm1: Math.PI/2, arm2: -Math.PI/2 };
        const limbSwing = { leg1: 0.2, leg2: 0.2, arm1: 0.15, arm2: 0.15 };
        const walkingDuration = 3000; // 3 seconds
        const runningDuration = 3000; // 3 seconds
        const standDuration = 2000; // 2 seconds

        let currentState = 'stand';
        let lastTime = performance.now();

        function animate(now) {
            const delta = now - lastTime;
            const t = delta / 10000; // total cycle time = 10s

            if (currentState === 'stand') {
                if (t >= 2) currentState = 'walk';
                leg1.rotation.z = limbRotation.leg1 + Math.sin(t * 2 * Math.PI) * 0.1;
                leg2.rotation.z = limbRotation.leg2 + Math.sin(t * 2 * Math.PI) * 0.1;
                arm1.rotation.z = limbRotation.arm1 + Math.sin(t * 1.5 * Math.PI) * 0.08;
                arm2.rotation.z = limbRotation.arm2 + Math.sin(t * 1.5 * Math.PI) * 0.08;
            } else if (currentState === 'walk') {
                if (t >= 5) currentState = 'run';
                leg1.rotation.z = limbRotation.leg1 + Math.sin(t * 1.5 * Math.PI) * 0.12;
                leg2.rotation.z = limbRotation.leg2 + Math.sin(t * 1.5 * Math.PI) * 0.12;
                arm1.rotation.z = limbRotation.arm1 + Math.sin(t * 1.2 * Math.PI) * 0.07;
                arm2.rotation.z = limbRotation.arm2 + Math.sin(t * 1.2 * Math.PI) * 0.07;
            } else if (currentState === 'run') {
                if (t >= 8) currentState = 'stand';
                leg1.rotation.z = limbRotation.leg1 + Math.sin(t * 2 * Math.PI) * 0.2;
                leg2.rotation.z = limbRotation.leg2 + Math.sin(t * 2 * Math.PI) * 0.2;
                arm1.rotation.z = limbRotation.arm1 + Math.sin(t * 2.5 * Math.PI) * 0.15;
                arm2.rotation.z = limbRotation.arm2 + Math.sin(t * 2.5 * Math.PI) * 0.15;
            }

            lastTime = now;
            requestAnimationFrame(animate);
        }

        animate();
    </script>
</body>
</html>
```
